const WHITELIST=["tableName","TABLE_NAME","tblName","orderBy","ORDER_BY","ORDER_COLUMN","sortColumn","SORT_COLUMN","sortOrder","SORT_ORDER","columns","COLUMNS","schemaName","SCHEMA_NAME","direction","DIR","prefix","suffix"];function checkDangerousBindings(filePath,content){const dangerous=[];const pattern=/\$\{([^}]+)\}/g;let match;while((match=pattern.exec(content))!==null){const paramName=match[1].trim();if(!WHITELIST.includes(paramName)){const lineStart=content.lastIndexOf("\n",match.index)+1;const lineEnd=content.indexOf("\n",match.index);const line=content.slice(lineStart,lineEnd===-1?undefined:lineEnd).trim();dangerous.push(line)}}return{dangerous:dangerous}}function onPreToolUse(event){const{tool_name,tool_input}=event;if(!["edit","write"].includes(tool_name.toLowerCase())){return{decision:"allow"}}const filePath=tool_input.file_path||"";if(!filePath.endsWith(".xml")){return{decision:"allow"}}const content=tool_name.toLowerCase()==="write"?tool_input.content||"":tool_input.new_string||"";if(!content){return{decision:"allow"}}const{dangerous}=checkDangerousBindings(filePath,content);if(dangerous.length===0){return{decision:"allow"}}const lines=dangerous.map(l=>`  - ${l}`).join("\n");const message=`━━━ MYBATIS SQL INJECTION GUARD ━━━━━━━━━━━━━━━\n`+`File: ${filePath}\n\n`+`Dangerous bindings detected (use #{} instead):\n`+`${lines}\n\n`+`Whitelisted: tableName, orderBy, sortColumn, columns, schemaName, direction\n`+`To add to whitelist: edit mybatisBindingGuard.js WHITELIST array\n`+`━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n`;return{decision:"block",message:message}}if(require.main===module){const chunks=[];process.stdin.setEncoding("utf8");process.stdin.on("data",chunk=>chunks.push(chunk));process.stdin.on("end",()=>{try{const input=chunks.join("");if(!input.trim()){process.exit(0)}const event=JSON.parse(input);const result=onPreToolUse(event);if(result.decision==="block"){if(result.message)process.stderr.write(result.message);process.exit(2)}process.exit(0)}catch(e){process.stderr.write(`[MyBatisBindingGuard] Parse error - allowing: ${e.message}\n`);process.exit(0)}});const safetyTimer=setTimeout(()=>{process.stderr.write("[MyBatisBindingGuard] stdin timeout - allowing\n");process.exit(0)},5e3);process.stdin.on("end",()=>clearTimeout(safetyTimer));process.stdin.resume()}module.exports={onPreToolUse:onPreToolUse,checkDangerousBindings:checkDangerousBindings,WHITELIST:WHITELIST};